#include "g2m/layer/landcover_classifier.h"
#include "g2m/core/hash.h"
#include "strict_json.h"
#include <cstdio>
#include <cstdlib>

namespace g2m {
namespace {
using json = nlohmann::json;
using strict::Reader;
// const unsigned char kEsaWorldcoverV200[]: the bytes of data/classifiers/esa_worldcover_v200.json, generated by CMake.
#include "esa_worldcover_v200.inc"

// ESA WorldCover v200 legend: the 11 codes the table must name, ascending.
constexpr std::uint8_t kEsaCodes[11] = {10, 20, 30, 40, 50, 60, 70, 80, 90, 95, 100};

struct LandName { const char* name; LandClass value; };
constexpr LandName kLandNames[] = {
    {"unknown", LandClass::Unknown}, {"paved_road", LandClass::PavedRoad}, {"unpaved_road", LandClass::UnpavedRoad},
    {"rail", LandClass::Rail}, {"water", LandClass::Water}, {"building", LandClass::Building},
    {"tree_cover", LandClass::TreeCover}, {"shrub", LandClass::Shrub}, {"grassland", LandClass::Grassland},
    {"cropland", LandClass::Cropland}, {"bare", LandClass::Bare}, {"built_up", LandClass::BuiltUp},
    {"wetland", LandClass::Wetland}, {"snow_ice", LandClass::SnowIce}};
struct SurfaceName { const char* name; SurfaceKind value; };
constexpr SurfaceName kSurfaceNames[] = {
    {"unknown", SurfaceKind::Unknown}, {"asphalt", SurfaceKind::Asphalt}, {"concrete", SurfaceKind::Concrete},
    {"paving_stones", SurfaceKind::PavingStones}, {"sett", SurfaceKind::Sett}, {"cobblestone", SurfaceKind::Cobblestone},
    {"gravel", SurfaceKind::Gravel}, {"compacted", SurfaceKind::Compacted}, {"dirt", SurfaceKind::Dirt},
    {"grass", SurfaceKind::Grass}, {"sand", SurfaceKind::Sand}, {"water", SurfaceKind::Water}};
} // namespace

Result<LandcoverClassifier> LandcoverClassifier::load(std::span<const std::byte> bytes) {
    const char* begin = reinterpret_cast<const char*>(bytes.data());
    const json j = json::parse(begin, begin + bytes.size(), nullptr, /*allow_exceptions=*/false);
    if (j.is_discarded()) return make_error(ErrorCode::Malformed, "classifier table: not valid JSON");
    Reader rd;
    const auto fail = [&]() { return make_error(ErrorCode::InvalidArgument, "classifier table: " + rd.err); };
    if (!rd.keys(j, "root", {"format", "name", "scheme", "classes", "sources"})) return fail();
    std::string format;
    if (!rd.text(j, "root", "format", format)) return fail();
    if (format != "g2m.classifier_table/1") return make_error(ErrorCode::Unsupported, "classifier table: format '" + format + "'");
    LandcoverClassifier out;
    if (!rd.text(j, "root", "name", out.name_) || !rd.text(j, "root", "scheme", out.scheme_)) return fail();
    if (out.name_.empty() || out.scheme_.empty()) { rd.fail("name and scheme must not be empty"); return fail(); }
    const auto* sources = rd.field(j, "root", "sources");
    if (!sources || !rd.object(*sources, "sources")) return fail();
    for (auto it = sources->begin(); it != sources->end(); ++it)
        if (!it.value().is_string()) { rd.fail("sources." + it.key() + " must be a string"); return fail(); }
    const auto* classes = rd.field(j, "root", "classes");
    if (!classes || !rd.object(*classes, "classes")) return fail();
    for (auto it = classes->begin(); it != classes->end(); ++it) {
        bool known = false;
        for (const auto code : kEsaCodes) known = known || it.key() == std::to_string(code);
        if (!known) { rd.fail("classes: unknown class '" + it.key() + "'"); return fail(); }
    }
    for (std::size_t i = 0; i < 11; ++i) {
        const std::string key = std::to_string(kEsaCodes[i]);
        const std::string path = "classes." + key;
        const auto it = classes->find(key);
        if (it == classes->end()) { rd.fail("classes: missing class '" + key + "'"); return fail(); }
        std::string land, surface;
        if (!rd.keys(*it, path, {"land_class", "surface"}) || !rd.text(*it, path, "land_class", land) ||
            !rd.text(*it, path, "surface", surface)) return fail();
        Entry& entry = out.entries_[i];
        entry.code = kEsaCodes[i];
        bool found = false;
        for (const auto& n : kLandNames) if (land == n.name) { entry.land_class = n.value; found = true; }
        if (!found) { rd.fail(path + ".land_class: unknown name '" + land + "'"); return fail(); }
        found = false;
        for (const auto& n : kSurfaceNames) if (surface == n.name) { entry.surface = n.value; found = true; }
        if (!found) { rd.fail(path + ".surface: unknown name '" + surface + "'"); return fail(); }
    }
    out.hash_ = Sha256::of(bytes);
    return out;
}

const LandcoverClassifier::Entry* LandcoverClassifier::find(std::uint8_t code) const {
    for (const Entry& e : entries_) if (e.code == code) return &e;
    return nullptr;
}
LandClass LandcoverClassifier::land_class(const ClassifierFacts& facts) const {
    if (facts.landcover_scheme != scheme_) return LandClass::Unknown;
    const Entry* e = find(facts.landcover_class);
    return e ? e->land_class : LandClass::Unknown;
}
SurfaceKind LandcoverClassifier::surface(const ClassifierFacts& facts) const {
    if (facts.landcover_scheme != scheme_) return SurfaceKind::Unknown;
    const Entry* e = find(facts.landcover_class);
    return e ? e->surface : SurfaceKind::Unknown;
}

std::span<const std::byte> builtin_esa_worldcover_classifier_bytes() {
    return {reinterpret_cast<const std::byte*>(kEsaWorldcoverV200), sizeof(kEsaWorldcoverV200)};
}
const LandcoverClassifier& builtin_esa_worldcover_classifier() {
    static const LandcoverClassifier table = [] {
        auto loaded = LandcoverClassifier::load(builtin_esa_worldcover_classifier_bytes());
        if (!loaded) {
            std::fprintf(stderr, "g2m: embedded data/classifiers/esa_worldcover_v200.json is invalid: %s\n", loaded.error().message.c_str());
            std::abort();
        }
        return std::move(*loaded);
    }();
    return table;
}
} // namespace g2m
